/** Builds the standard 7-block structure shared by every page in this content set. */
function standardBlocks(
    string $name,
    array $professionalParas,
    array $whyMattersParas,
    array $included,     // 8x [title, body]
    array $processSteps, // 6x [title, body]
    array $builtForParas,
    array $outcomes,      // 6 strings
    array $whyChoose      // 5x [title, body]
): array {
    return [
        ['kind' => 'paras', 'heading' => "Professional $name from Shrinath Solutions", 'items' => $professionalParas],
        ['kind' => 'paras', 'heading' => 'Why This Service Matters', 'items' => $whyMattersParas],
        ['kind' => 'cards', 'heading' => 'What Is Included', 'items' => array_map(fn($i) => ['title' => $i[0], 'body' => $i[1]], $included)],
        ['kind' => 'steps', 'heading' => "Our $name Process", 'items' => array_map(fn($s, $i) => ['num' => sprintf('%02d', $i + 1), 'title' => $s[0], 'body' => $s[1]], $processSteps, array_keys($processSteps))],
        ['kind' => 'paras', 'heading' => 'Built for Hotels, Travel Brands and Growing Businesses', 'items' => $builtForParas],
        ['kind' => 'ticks', 'heading' => 'Outcomes We Work Towards', 'items' => $outcomes],
        ['kind' => 'cards', 'heading' => 'Why Choose Shrinath Solutions?', 'items' => array_map(fn($i) => ['title' => $i[0], 'body' => $i[1]], $whyChoose)],
    ];
}

