            'name' => $s['name'], 'slug' => $s['slug'], 'category' => $s['category'],
            'hero_label' => $s['category'], 'h1' => $s['h1'], 'hero_description' => $s['hero_description'],
            'hero_cta_label' => 'Get a Free Consultation', 'blocks' => $blocks,
            'cta_heading' => 'Get a Free Consultation', 'cta_body' => $s['cta_body'],
            'status' => 'published', 'menu_visibility' => true, 'display_order' => 100 + $createdCount,
        ], $adminId);

        save_seo_meta($pdo, 'service', $id, [
            'meta_title' => $s['meta_title'],
            'meta_description' => $s['meta_description'],
            'canonical_url' => 'https://shrinathsolutions.com/' . trim($s['slug'], '/'),
        ]);
        save_faqs($pdo, 'service', $id, $faqs);

        $pdo->commit();
        $slugBySimpleName[$s['name']] = $s['slug'];
        echo "Seeded: {$s['slug']} (id $id)\n";
        $createdCount++;
    } catch (Throwable $e) {
        $pdo->rollBack();
        fwrite(STDERR, "Failed to seed {$s['slug']}: " . $e->getMessage() . "\n");
    }
}

echo "\nCreated $createdCount, skipped $skippedCount (already existed).\n";

// ===================== Second pass: resolve related_json against the DB's current full state =====================
// Re-run every time (not just for services created this run) so that pages seeded in an
// earlier invocation get their related links backfilled once the pages they reference exist.
$knownSlugs = [
    'Website Designing and Development' => 'website-designing',
    'Online Marketing Services' => 'online-marketing',
    'SEO Services' => 'seo-services',
    'Hotel Digital Marketing' => 'hotel-digital-marketing',
    'Hotel Channel Manager and Cloud PMS' => 'channel-manager-hotel-software',
];
$dbSlugs = $pdo->query('SELECT name, slug FROM services')->fetchAll(PDO::FETCH_KEY_PAIR);
$allKnown = array_merge($knownSlugs, $dbSlugs, $slugBySimpleName);

foreach ($services as $s) {
    if (!service_slug_taken($pdo, $s['slug'], null)) {
        continue; // this page doesn't exist in the DB at all (shouldn't happen after the insert pass, but be safe)
    }
    $related = [];
    foreach ($s['related_names'] as $relName) {
        if (isset($categoryRoutes[$relName])) {
            $related[] = ['label' => $relName, 'to' => $categoryRoutes[$relName]];
        } elseif (isset($allKnown[$relName])) {
            $related[] = ['label' => $relName, 'to' => '/services/' . $allKnown[$relName]];
        }
    }
    $related[] = ['label' => 'Contact', 'to' => '/contact'];

    $stmt = $pdo->prepare('UPDATE services SET related_json = :r WHERE slug = :slug');
    $stmt->execute(['r' => json_encode($related), 'slug' => $s['slug']]);
}

echo "Related links resolved.\n";
